import math

def sum_of_divisors(n):
    sum_div = 0
    for i in range(1, int(math.isqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                sum_div += i
            else:
                sum_div += i + n // i
    return sum_div

