# Find possible values for a and c such that 2a = 5c and a, c are integers from 1 to 9
possible_values = []
for a in range(1, 10):
    for c in range(1, 10):
        if 2 * a == 5 * c:
            possible_values.append((a, c))

# Now use equation 3: 2a = d + c to find d
# Then use equation 1: a + b = d to find b
solutions = []
for a, c in possible_values:
    d = 2 * a - c
    if 1 <= d <= 9 and d != a and d != c:
        b = d - a
        if 1 <= b <= 9 and b != a and b != c and b != d:
            solutions.append((a, b, c, d))

